fn now_utc_iso() -> String {
    let now = SystemTime::now();
    let duration = now.duration_since(UNIX_EPOCH).unwrap_or_default();
    let secs = duration.as_secs();
    let micros = duration.subsec_micros();

    let days = (secs / 86400) as i64;
    let time_secs = secs % 86400;
    let hours = time_secs / 3600;
    let minutes = (time_secs % 3600) / 60;
    let seconds = time_secs % 60;

    let z = days + 719468;
    let era = (if z >= 0 { z } else { z - 146096 }) / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = (yoe as i64) + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };

    format!(
        "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}Z",
        y, m, d, hours, minutes, seconds, micros
    )
}

fn parse_size(s: &str) -> Result<u64, String> {
    let s = s.trim();
    if s.is_empty() {
        return Err("empty string".into());
    }
    let (num_str, mult) = if let Some(stripped) = s.strip_suffix('k') {
        (stripped, 1024u64)
    } else if let Some(stripped) = s.strip_suffix('M') {
        (stripped, 1024 * 1024u64)
    } else if let Some(stripped) = s.strip_suffix('G') {
        (stripped, 1024 * 1024 * 1024u64)
    } else if let Some(stripped) = s.strip_suffix('T') {
        (stripped, 1024 * 1024 * 1024 * 1024u64)
    } else {
        (s, 1u64)
    };

    let n: u64 = num_str.parse().map_err(|_| "invalid digit found in string".to_string())?;
    Ok(n * mult)
}

fn check_socket_buffer_sizes(socket: &UdpSocket, send_size: Option<u64>, recv_size: Option<u64>) {
    if let Some(desired) = send_size {
        let _ = socket.set_send_buffer_size(desired as usize);
        if let Ok(actual) = socket.send_buffer_size() {
            if (actual as u64) < desired {
                eprintln!(
                    "{}  WARN perf: Unable to set desired send buffer size. Desired: {}, Actual: {}",
                    now_utc_iso(),
                    desired,
                    actual
                );
            }
        }
    }
    if let Some(desired) = recv_size {
        let _ = socket.set_recv_buffer_size(desired as usize);
        if let Ok(actual) = socket.recv_buffer_size() {
            if (actual as u64) < desired {
                eprintln!(
                    "{}  WARN perf: Unable to set desired recv buffer size. Desired: {}, Actual: {}",
                    now_utc_iso(),
                    desired,
                    actual
                );
            }
        }
    }
}

