            .help("Maximum number of bytes to transmit to a peer without acknowledgment")
            .long_help("Maximum number of bytes to transmit to a peer without acknowledgment\n\nThis can use SI suffixes for sizes. For example, 1M will limit to 1MiB, 10G will limit to 10GiB.")
            .value_parser(parse_size),
    )
    .arg(
        Arg::new("max-udp-payload-size")
            .long("max-udp-payload-size")
            .value_name("MAX_UDP_PAYLOAD_SIZE")
            .help("Max UDP payload size in bytes")
            .default_value("1472")
            .value_parser(clap::value_parser!(u64)),
    )
    .arg(
        Arg::new("qlog")
            .long("qlog")
            .value_name("QLOG_FILE")
            .help("qlog output file"),
    )
}

fn format_duration(dur: Duration) -> String {
    let nanos = dur.as_nanos();
    if nanos < 1000 {
        format!("{:.2}ns", nanos as f64)
    } else if nanos < 1_000_000 {
        format!("{:.2}µs", nanos as f64 / 1_000.0)
    } else if nanos < 1_000_000_000 {
        format!("{:.2}ms", nanos as f64 / 1_000_000.0)
    } else {
        format!("{:.2}s", nanos as f64 / 1_000_000_000.0)
    }
}

fn quantile(sorted: &[f64], p: f64) -> f64 {
    if sorted.is_empty() {
        return 0.0;
    }
    if sorted.len() == 1 {
        return sorted[0];
    }
    let k = (sorted.len() - 1) as f64 * p;
    let i = k.floor() as usize;
    let f = k - (i as f64);
    if i + 1 < sorted.len() {
        sorted[i] + f * (sorted[i + 1] - sorted[i])
    } else {
        sorted[i]
    }
}

