fn write_json_output(
    records: &[StreamRecord],
    start_unix_secs: u64,
    out_path: &str,
    interval_secs: u64,
    duration_secs: u64,
) {
    let mut num_intervals = (duration_secs / interval_secs).max(1);
    if duration_secs % interval_secs != 0 {
        num_intervals += 1;
    }

    let mut intervals = Vec::new();

    for i in 0..num_intervals {
        let interval_start_sec = (i * interval_secs) as f64;
        let interval_end_sec = ((i + 1) * interval_secs).min(duration_secs) as f64;

        let interval_records: Vec<&StreamRecord> = records
            .iter()
            .filter(|r| r.start_sec >= interval_start_sec && r.start_sec < interval_end_sec)
            .collect();

        let mut streams = Vec::new();
        let mut total_bytes = 0u64;

        for r in &interval_records {
            let up_bps = if r.upload_dur.as_secs_f64() > 0.0 {
                (r.upload_bytes as f64 * 8.0) / r.upload_dur.as_secs_f64()
            } else {
                0.0
            };

            streams.push(JsonStream {
                id: r.id,
                start: r.start_sec,
                end: r.upload_end_sec,
                seconds: r.upload_dur.as_secs_f64(),
                bytes: r.upload_bytes,
                bits_per_second: up_bps,
                sender: true,
            });
            total_bytes += r.upload_bytes;

            if !r.is_uni {
                let down_bps = if r.download_dur.as_secs_f64() > 0.0 {
                    (r.download_bytes as f64 * 8.0) / r.download_dur.as_secs_f64()
                } else {
                    0.0
                };

                streams.push(JsonStream {
                    id: r.id,
                    start: r.start_sec,
                    end: r.download_end_sec,
                    seconds: r.download_dur.as_secs_f64(),
                    bytes: r.download_bytes,
                    bits_per_second: down_bps,
                    sender: false,
                });
                total_bytes += r.download_bytes;
            }
        }

        let dur_sec = (interval_end_sec - interval_start_sec).max(0.001);
        let sum_bps = (total_bytes as f64 * 8.0) / dur_sec;

        intervals.push(JsonInterval {
            streams,
            sum: JsonStreamSum {
                start: interval_start_sec,
                end: interval_end_sec,
                seconds: dur_sec,
                bytes: total_bytes,
                bits_per_second: sum_bps,
                sender: true,
            },
        });
    }

    let json_obj = JsonOutput {
        start: JsonStart {
            timestamp: JsonTimestamp {
                timesecs: start_unix_secs,
            },
        },
        intervals,
    };

    let json_str = serde_json::to_string(&json_obj).unwrap_or_default();

    if out_path == "-" {
        println!("{}", json_str);
    } else {
        if let Ok(mut f) = File::create(out_path) {
            let _ = f.write_all(json_str.as_bytes());
        }
    }
}

fn main() {
    let server_cmd = common_opts(
        Command::new("server")
            .about("Run as a perf server")
            .arg(
