fn run_server(matches: &clap::ArgMatches) {
    let listen_str: &String = matches.get_one("listen").unwrap();
    let key: Option<&String> = matches.get_one("key");
    let cert: Option<&String> = matches.get_one("cert");
    let send_buf: Option<&u64> = matches.get_one("send-buffer-size");
    let recv_buf: Option<&u64> = matches.get_one("recv-buffer-size");

    if let Some(key_path) = key {
        if !std::path::Path::new(key_path).exists() {
            eprintln!(
                "{} ERROR quinn_perf: reading private key: I/O error: No such file or directory (os error 2)",
                now_utc_iso()
            );
            return;
        }
    }
    if let Some(cert_path) = cert {
        if !std::path::Path::new(cert_path).exists() {
            eprintln!(
                "{} ERROR quinn_perf: reading certificate: I/O error: No such file or directory (os error 2)",
                now_utc_iso()
            );
            return;
        }
    }

    let listen_addr: SocketAddr = match listen_str.parse() {
        Ok(addr) => addr,
        Err(e) => {
            eprintln!("{} ERROR quinn_perf: binding endpoint: {}", now_utc_iso(), e);
            return;
        }
    };

    let udp_socket = match UdpSocket::bind(listen_addr) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{} ERROR quinn_perf: binding endpoint: {}", now_utc_iso(), e);
            return;
        }
    };

    check_socket_buffer_sizes(&udp_socket, send_buf.copied(), recv_buf.copied());

    let tcp_listener = match TcpListener::bind(listen_addr) {
        Ok(l) => l,
        Err(_) => match TcpListener::bind(SocketAddr::new(listen_addr.ip(), 0)) {
            Ok(l) => l,
            Err(e) => {
                eprintln!("{} ERROR quinn_perf: binding tcp endpoint: {}", now_utc_iso(), e);
                return;
            }
        },
    };

    let local_tcp_port = tcp_listener.local_addr().unwrap().port();

    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    thread::spawn(move || {
        let mut buf = [0u8; 1024];
        while r.load(Ordering::Relaxed) {
            if let Ok((amt, src)) = udp_socket.recv_from(&mut buf) {
                if amt >= 4 && &buf[0..4] == b"PING" {
                    let mut resp = Vec::new();
                    resp.extend_from_slice(b"PONG");
                    resp.extend_from_slice(&local_tcp_port.to_be_bytes());
                    let _ = udp_socket.send_to(&resp, src);
                }
            }
        }
    });

    for stream in tcp_listener.incoming() {
        if let Ok(mut socket) = stream {
            thread::spawn(move || {
                let mut header = [0u8; 17];
                while socket.read_exact(&mut header).is_ok() {
                    let is_uni = header[0] != 0;
                    let _stream_id = u64::from_be_bytes(header[1..9].try_into().unwrap());
                    let download_size = u64::from_be_bytes(header[9..17].try_into().unwrap());

                    let mut len_buf = [0u8; 8];
                    if socket.read_exact(&mut len_buf).is_err() {
                        break;
                    }
                    let upload_size = u64::from_be_bytes(len_buf);

                    let mut remaining = upload_size;
                    let mut dummy = [0u8; 65536];
                    while remaining > 0 {
                        let to_read = remaining.min(dummy.len() as u64) as usize;
                        if socket.read_exact(&mut dummy[..to_read]).is_err() {
                            break;
                        }
                        remaining -= to_read as u64;
                    }

                    if !is_uni {
                        let mut rem_out = download_size;
                        let zeros = [0u8; 65536];
                        while rem_out > 0 {
