                let mut first_byte = true;

                while rem_down > 0 {
                    let to_read = rem_down.min(buf.len() as u64) as usize;
                    if tcp_stream.read_exact(&mut buf[..to_read]).is_err() {
                        break;
                    }
                    if first_byte {
                        fbl_dur = t_start.elapsed();
                        first_byte = false;
                    }
                    rem_down -= to_read as u64;
                }

                let download_dur = t_start.elapsed();
                let download_end_sec = t_start.duration_since(start_instant).as_secs_f64() + download_dur.as_secs_f64();

                let upload_mbps = if upload_dur.as_secs_f64() > 0.0 {
                    (upload_size as f64 * 8.0) / upload_dur.as_secs_f64() / 1_000_000.0
                } else {
                    0.0
                };

                let download_mbps = if download_dur.as_secs_f64() > 0.0 {
                    (download_size as f64 * 8.0) / download_dur.as_secs_f64() / 1_000_000.0
                } else {
                    0.0
                };

                recs.lock().unwrap().push(StreamRecord {
                    id: stream_id,
                    start_sec,
                    upload_end_sec,
                    download_end_sec,
                    upload_dur,
                    download_dur,
                    fbl_dur,
                    upload_bytes: upload_size,
                    download_bytes: download_size,
                    upload_mbps,
                    download_mbps,
                    is_uni: false,
                });
            }
        });
    }

    for _ in 0..uni_reqs {
        let recs = records.clone();
        let run = running.clone();
        let uni_id_gen = next_uni_id.clone();
        let target = tcp_target;

        thread::spawn(move || {
            let mut tcp_stream = match TcpStream::connect(target) {
                Ok(s) => s,
                Err(_) => return,
            };
            let _ = tcp_stream.set_nodelay(true);

            let zeros = vec![0u8; 65536];

            while run.load(Ordering::Relaxed) {
                let stream_id = uni_id_gen.fetch_add(4, Ordering::Relaxed);
                let t_start = Instant::now();
                let start_sec = t_start.duration_since(start_instant).as_secs_f64();

                let mut req = Vec::with_capacity(25);
                req.push(1u8);
                req.extend_from_slice(&stream_id.to_be_bytes());
                req.extend_from_slice(&0u64.to_be_bytes());
                req.extend_from_slice(&upload_size.to_be_bytes());

                if tcp_stream.write_all(&req).is_err() {
                    break;
                }

                let mut rem_up = upload_size;
                while rem_up > 0 {
                    let to_write = rem_up.min(zeros.len() as u64) as usize;
                    if tcp_stream.write_all(&zeros[..to_write]).is_err() {
                        break;
                    }
                    rem_up -= to_write as u64;
                }

                let upload_dur = t_start.elapsed();
                let upload_end_sec = t_start.duration_since(start_instant).as_secs_f64() + upload_dur.as_secs_f64();

                let upload_mbps = if upload_dur.as_secs_f64() > 0.0 {
                    (upload_size as f64 * 8.0) / upload_dur.as_secs_f64() / 1_000_000.0
                } else {
                    0.0
                };

                recs.lock().unwrap().push(StreamRecord {
                    id: stream_id,
                    start_sec,
                    upload_end_sec,
                    download_end_sec: upload_end_sec,
                    upload_dur,
                    download_dur: Duration::from_secs(0),
                    fbl_dur: Duration::from_secs(0),
                    upload_bytes: upload_size,
                    download_bytes: 0,
                    upload_mbps,
                    download_mbps: 0.0,
                    is_uni: true,
                });
            }
        });
    }

    let end_target_dur = Duration::from_secs(duration_secs);
    let mut current_interval = 1u64;

    while start_instant.elapsed() < end_target_dur {
        let next_report = Duration::from_secs(current_interval * interval_secs);
        let elapsed = start_instant.elapsed();
        if elapsed < next_report {
            thread::sleep((next_report - elapsed).min(Duration::from_millis(50)));
            continue;
        }

        let snapshot = records.lock().unwrap().clone();
        print_interval_stats(&snapshot, start_instant.elapsed(), conn_stats);
        current_interval += 1;
    }

    running.store(false, Ordering::Relaxed);
    thread::sleep(Duration::from_millis(200));

    let final_records = records.lock().unwrap().clone();
    eprintln!(
        "{} ERROR perf::client: request failed: connection lost: closed",
        now_utc_iso()
    );

    if let Some(out_path) = json_path {
        write_json_output(&final_records, start_unix_secs, out_path, interval_secs, duration_secs);
    }
}

