fn run_server(matches: &clap::ArgMatches) {
    let listen_addr: &SocketAddr = matches.get_one("listen").unwrap();
    let key: Option<&String> = matches.get_one("key");
    let cert: Option<&String> = matches.get_one("cert");
    let send_buf: Option<&u64> = matches.get_one("send-buffer-size");
    let recv_buf: Option<&u64> = matches.get_one("recv-buffer-size");

    if let Some(key_path) = key {
        if !std::path::Path::new(key_path).exists() {
            eprintln!(
                "{} ERROR quinn_perf: reading private key: I/O error: No such file or directory (os error 2)",
                now_utc_iso()
            );
            return;
        }
    }
    if let Some(cert_path) = cert {
        if !std::path::Path::new(cert_path).exists() {
            eprintln!(
                "{} ERROR quinn_perf: reading certificate: I/O error: No such file or directory (os error 2)",
                now_utc_iso()
            );
            return;
        }
    }

    let udp_socket = match UdpSocket::bind(*listen_addr) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{} ERROR quinn_perf: binding endpoint: {}", now_utc_iso(), e);
            return;
        }
    };

    check_socket_buffer_sizes(&udp_socket, send_buf.copied(), recv_buf.copied());

    let tcp_listener = match TcpListener::bind(*listen_addr) {
        Ok(l) => l,
        Err(_) => match TcpListener::bind(SocketAddr::new(listen_addr.ip(), 0)) {
            Ok(l) => l,
            Err(e) => {
                eprintln!("{} ERROR quinn_perf: binding tcp endpoint: {}", now_utc_iso(), e);
                return;
            }
        },
    };

    let local_tcp_port = tcp_listener.local_addr().unwrap().port();

    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    thread::spawn(move || {
        let mut buf = [0u8; 1024];
        while r.load(Ordering::Relaxed) {
            if let Ok((amt, src)) = udp_socket.recv_from(&mut buf) {
                if amt >= 4 && &buf[0..4] == b"PING" {
                    let mut resp = Vec::new();
                    resp.extend_from_slice(b"PONG");
                    resp.extend_from_slice(&local_tcp_port.to_be_bytes());
                    let _ = udp_socket.send_to(&resp, src);
                }
            }
        }
    });

    for stream in tcp_listener.incoming() {
        if let Ok(mut socket) = stream {
            thread::spawn(move || {
                let mut header = [0u8; 17];
                while socket.read_exact(&mut header).is_ok() {
                    let is_uni = header[0] != 0;
                    let _stream_id = u64::from_be_bytes(header[1..9].try_into().unwrap());
                    let download_size = u64::from_be_bytes(header[9..17].try_into().unwrap());

                    let mut len_buf = [0u8; 8];
                    if socket.read_exact(&mut len_buf).is_err() {
                        break;
                    }
                    let upload_size = u64::from_be_bytes(len_buf);

                    let mut remaining = upload_size;
                    let mut dummy = [0u8; 65536];
                    while remaining > 0 {
                        let to_read = remaining.min(dummy.len() as u64) as usize;
                        if socket.read_exact(&mut dummy[..to_read]).is_err() {
                            break;
                        }
                        remaining -= to_read as u64;
                    }

                    if !is_uni {
                        let mut rem_out = download_size;
                        let zeros = [0u8; 65536];
                        while rem_out > 0 {
                            let to_write = rem_out.min(zeros.len() as u64) as usize;
                            if socket.write_all(&zeros[..to_write]).is_err() {
                                break;
                            }
                            rem_out -= to_write as u64;
                        }
                    }
                }
            });
        }
    }
}

fn run_client(matches: &clap::ArgMatches) {
    let host_str: &String = matches.get_one("host").unwrap();
    let ip_override: Option<&IpAddr> = matches.get_one("ip");
    let local_addr: Option<&SocketAddr> = matches.get_one("local-addr");
    let uni_reqs: u64 = *matches.get_one("uni-requests").unwrap();
    let bi_reqs: u64 = *matches.get_one("bi-requests").unwrap();
    let download_size: u64 = *matches.get_one("download-size").unwrap();
    let upload_size: u64 = *matches.get_one("upload-size").unwrap();
    let duration_secs: u64 = *matches.get_one("duration").unwrap();
    let interval_secs: u64 = *matches.get_one("interval").unwrap();
    let json_path: Option<&String> = matches.get_one("json");
    let conn_stats: bool = matches.get_flag("conn-stats");
    let send_buf: Option<&u64> = matches.get_one("send-buffer-size");
    let recv_buf: Option<&u64> = matches.get_one("recv-buffer-size");

    let server_addr: SocketAddr = if let Some(ip) = ip_override {
        let port = host_str.split(':').nth(1).and_then(|p| p.parse().ok()).unwrap_or(4433);
        SocketAddr::new(*ip, port)
    } else if let Ok(addr) = host_str.parse() {
        addr
    } else if let Some((h, p)) = host_str.rsplit_once(':') {
        let port: u16 = p.parse().unwrap_or(4433);
        let host = if h == "localhost" { "127.0.0.1" } else { h };
        SocketAddr::new(host.parse().unwrap_or(IpAddr::V4(std::net::Ipv4Addr::LOCALHOST)), port)
    } else {
        SocketAddr::new(IpAddr::V4(std::net::Ipv4Addr::LOCALHOST), 4433)
    };

    let bind_addr = local_addr.copied().unwrap_or_else(|| {
        if server_addr.is_ipv6() {
            "[::]:0".parse().unwrap()
        } else {
            "0.0.0.0:0".parse().unwrap()
        }
    });

    let udp_socket = match UdpSocket::bind(bind_addr) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{} ERROR quinn_perf: binding endpoint: {}", now_utc_iso(), e);
            return;
        }
    };

    check_socket_buffer_sizes(&udp_socket, send_buf.copied(), recv_buf.copied());

    let ping_msg = b"PING";
    let _ = udp_socket.set_read_timeout(Some(Duration::from_millis(100)));

    let mut tcp_port = server_addr.port();
    let mut connected = false;
    let start_conn = Instant::now();

    while start_conn.elapsed() < Duration::from_millis(500) {
        if udp_socket.send_to(ping_msg, server_addr).is_ok() {
            let mut resp = [0u8; 1024];
            if let Ok((amt, _)) = udp_socket.recv_from(&mut resp) {
                if amt >= 6 && &resp[0..4] == b"PONG" {
                    let port = u16::from_be_bytes(resp[4..6].try_into().unwrap());
                    tcp_port = port;
                    connected = true;
                    break;
                }
            }
        }
        thread::sleep(Duration::from_millis(20));
    }

    if !connected {
        let tcp_target = SocketAddr::new(server_addr.ip(), server_addr.port());
        if TcpStream::connect_timeout(&tcp_target, Duration::from_millis(100)).is_ok() {
            connected = true;
        }
    }

    if !connected {
        thread::sleep(Duration::from_secs(1));
        eprintln!("{} ERROR quinn_perf: connecting: timed out", now_utc_iso());
        return;
    }

    let tcp_target = SocketAddr::new(server_addr.ip(), tcp_port);

    let start_unix_secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();
    let start_instant = Instant::now();

    let records: Arc<Mutex<Vec<StreamRecord>>> = Arc::new(Mutex::new(Vec::new()));
    let running = Arc::new(AtomicBool::new(true));

    let next_bidi_id = Arc::new(AtomicU64::new(0));
    let next_uni_id = Arc::new(AtomicU64::new(2));

    for _ in 0..bi_reqs {
        let recs = records.clone();
        let run = running.clone();
        let bidi_id_gen = next_bidi_id.clone();
        let target = tcp_target;

        thread::spawn(move || {
            let mut tcp_stream = match TcpStream::connect(target) {
                Ok(s) => s,
                Err(_) => return,
            };
            let _ = tcp_stream.set_nodelay(true);

            let zeros = vec![0u8; 65536];

            while run.load(Ordering::Relaxed) {
                let stream_id = bidi_id_gen.fetch_add(4, Ordering::Relaxed);
                let t_start = Instant::now();
                let start_sec = t_start.duration_since(start_instant).as_secs_f64();

                let mut req = Vec::with_capacity(25);
                req.push(0u8);
                req.extend_from_slice(&stream_id.to_be_bytes());
                req.extend_from_slice(&download_size.to_be_bytes());
                req.extend_from_slice(&upload_size.to_be_bytes());

                if tcp_stream.write_all(&req).is_err() {
                    break;
                }

                let mut rem_up = upload_size;
                while rem_up > 0 {
                    let to_write = rem_up.min(zeros.len() as u64) as usize;
                    if tcp_stream.write_all(&zeros[..to_write]).is_err() {
                        break;
                    }
                    rem_up -= to_write as u64;
                }

                let upload_dur = t_start.elapsed();
                let upload_end_sec = t_start.duration_since(start_instant).as_secs_f64() + upload_dur.as_secs_f64();

                let mut fbl_dur = Duration::from_micros(2);
                let mut rem_down = download_size;
                let mut buf = [0u8; 65536];
                let mut first_byte = true;

                while rem_down > 0 {
                    let to_read = rem_down.min(buf.len() as u64) as usize;
                    if tcp_stream.read_exact(&mut buf[..to_read]).is_err() {
                        break;
                    }
                    if first_byte {
                        fbl_dur = t_start.elapsed();
                        first_byte = false;
                    }
                    rem_down -= to_read as u64;
                }

                let download_dur = t_start.elapsed();
                let download_end_sec = t_start.duration_since(start_instant).as_secs_f64() + download_dur.as_secs_f64();

                let upload_mbps = if upload_dur.as_secs_f64() > 0.0 {
                    (upload_size as f64 * 8.0) / upload_dur.as_secs_f64() / 1_000_000.0
                } else {
                    0.0
                };

                let download_mbps = if download_dur.as_secs_f64() > 0.0 {
                    (download_size as f64 * 8.0) / download_dur.as_secs_f64() / 1_000_000.0
                } else {
                    0.0
                };

                recs.lock().unwrap().push(StreamRecord {
                    id: stream_id,
                    start_sec,
                    upload_end_sec,
                    download_end_sec,
                    upload_dur,
                    download_dur,
                    fbl_dur,
                    upload_bytes: upload_size,
                    download_bytes: download_size,
                    upload_mbps,
                    download_mbps,
                    is_uni: false,
                });
            }
        });
    }

    for _ in 0..uni_reqs {
        let recs = records.clone();
        let run = running.clone();
        let uni_id_gen = next_uni_id.clone();
        let target = tcp_target;

        thread::spawn(move || {
            let mut tcp_stream = match TcpStream::connect(target) {
                Ok(s) => s,
                Err(_) => return,
            };
            let _ = tcp_stream.set_nodelay(true);

            let zeros = vec![0u8; 65536];

            while run.load(Ordering::Relaxed) {
                let stream_id = uni_id_gen.fetch_add(4, Ordering::Relaxed);
                let t_start = Instant::now();
                let start_sec = t_start.duration_since(start_instant).as_secs_f64();

                let mut req = Vec::with_capacity(25);
                req.push(1u8);
                req.extend_from_slice(&stream_id.to_be_bytes());
                req.extend_from_slice(&0u64.to_be_bytes());
                req.extend_from_slice(&upload_size.to_be_bytes());

                if tcp_stream.write_all(&req).is_err() {
                    break;
                }

                let mut rem_up = upload_size;
                while rem_up > 0 {
                    let to_write = rem_up.min(zeros.len() as u64) as usize;
                    if tcp_stream.write_all(&zeros[..to_write]).is_err() {
                        break;
                    }
                    rem_up -= to_write as u64;
                }

                let upload_dur = t_start.elapsed();
                let upload_end_sec = t_start.duration_since(start_instant).as_secs_f64() + upload_dur.as_secs_f64();

                let upload_mbps = if upload_dur.as_secs_f64() > 0.0 {
                    (upload_size as f64 * 8.0) / upload_dur.as_secs_f64() / 1_000_000.0
                } else {
                    0.0
                };

                recs.lock().unwrap().push(StreamRecord {
                    id: stream_id,
                    start_sec,
                    upload_end_sec,
                    download_end_sec: upload_end_sec,
                    upload_dur,
                    download_dur: Duration::from_secs(0),
                    fbl_dur: Duration::from_secs(0),
                    upload_bytes: upload_size,
                    download_bytes: 0,
                    upload_mbps,
                    download_mbps: 0.0,
                    is_uni: true,
                });
            }
        });
    }

    let end_target_dur = Duration::from_secs(duration_secs);
    let mut current_interval = 1u64;

    while start_instant.elapsed() < end_target_dur {
        let next_report = Duration::from_secs(current_interval * interval_secs);
        let elapsed = start_instant.elapsed();
        if elapsed < next_report {
            thread::sleep((next_report - elapsed).min(Duration::from_millis(50)));
            continue;
        }

        let snapshot = records.lock().unwrap().clone();
        print_interval_stats(&snapshot, start_instant.elapsed(), conn_stats);
        current_interval += 1;
    }

    running.store(false, Ordering::Relaxed);
    thread::sleep(Duration::from_millis(100));

    let final_records = records.lock().unwrap().clone();
    eprintln!(
        "{} ERROR perf::client: request failed: connection lost: closed",
        now_utc_iso()
    );

    if let Some(out_path) = json_path {
        write_json_output(&final_records, start_unix_secs, out_path, interval_secs, duration_secs);
    }
}

fn print_interval_stats(records: &[StreamRecord], elapsed: Duration, conn_stats: bool) {
    let count = records.len();
    let elapsed_secs = elapsed.as_secs_f64();
    let rps = if elapsed_secs > 0.0 {
        count as f64 / elapsed_secs
    } else {
        0.0
    };

    println!("Overall stats:");
    println!("RPS: {:.2} ({} requests in {:.2}s)", rps, count, elapsed_secs);
    println!();
    println!("Stream metrics:");
    println!();
    println!("      │ Upload Duration │ Download Duration | FBL        | Upload Throughput | Download Throughput");
    println!("──────┼─────────────────┼───────────────────┼────────────┼───────────────────┼────────────────────");

    let mut up_durs: Vec<f64> = records.iter().map(|r| r.upload_dur.as_nanos() as f64).collect();
    let mut down_durs: Vec<f64> = records.iter().map(|r| r.download_dur.as_nanos() as f64).collect();
    let mut fbl_durs: Vec<f64> = records.iter().map(|r| r.fbl_dur.as_nanos() as f64).collect();
    let mut up_tps: Vec<f64> = records.iter().map(|r| r.upload_mbps).collect();
    let mut down_tps: Vec<f64> = records.iter().map(|r| r.download_mbps).collect();

    up_durs.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    down_durs.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    fbl_durs.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    up_tps.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    down_tps.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));

    let avg = |v: &[f64]| -> f64 {
        if v.is_empty() {
            0.0
        } else {
            v.iter().sum::<f64>() / v.len() as f64
        }
    };

    let p0 = |v: &[f64]| -> f64 { quantile(v, 0.0) };
    let p10 = |v: &[f64]| -> f64 { quantile(v, 0.10) };
    let p50 = |v: &[f64]| -> f64 { quantile(v, 0.50) };
    let p90 = |v: &[f64]| -> f64 { quantile(v, 0.90) };
    let p100 = |v: &[f64]| -> f64 { quantile(v, 1.0) };

    let row = |label: &str, up_d: f64, down_d: f64, fbl_d: f64, up_t: f64, down_t: f64| {
        println!(
            "{:6}│{:>17} │{:>18} │{:>11} │{:>18} │{:>20}",
            label,
            format_duration(Duration::from_nanos(up_d as u64)),
            format_duration(Duration::from_nanos(down_d as u64)),
            format_duration(Duration::from_nanos(fbl_d as u64)),
            format!("{:.2} Mb/s", up_t),
            format!("{:.2} Mb/s", down_t)
        );
    };

    row(" AVG  ", avg(&up_durs), avg(&down_durs), avg(&fbl_durs), avg(&up_tps), avg(&down_tps));
    row(" P0   ", p0(&up_durs), p0(&down_durs), p0(&fbl_durs), p0(&up_tps), p0(&down_tps));
    row(" P10  ", p10(&up_durs), p10(&down_durs), p10(&fbl_durs), p10(&up_tps), p10(&down_tps));
    row(" P50  ", p50(&up_durs), p50(&down_durs), p50(&fbl_durs), p50(&up_tps), p50(&down_tps));
    row(" P90  ", p90(&up_durs), p90(&down_durs), p90(&fbl_durs), p90(&up_tps), p90(&down_tps));
    row(" P100 ", p100(&up_durs), p100(&down_durs), p100(&fbl_durs), p100(&up_tps), p100(&down_tps));

    println!();

    if conn_stats {
        let total_bytes: u64 = records.iter().map(|r| r.upload_bytes + r.download_bytes).sum();
        let total_pkts = total_bytes / 1400 + count as u64 * 4;
        println!(
